// رسالة واردة من محادثة فردية فقط (لا الرسائل المرسلة منا ولا المجموعات): نص، أو صورة (لكشف الدوام)
const body = $input.first().json.body || $input.first().json;
const d = body.data || {};
const key = d.key || {};
if (key.fromMe) return [];
let jid = key.remoteJid || '';
if (jid.endsWith('@g.us') || jid === 'status@broadcast') return [];
// في بعض الإصدارات يأتي المعرّف بصيغة @lid والرقم الحقيقي في حقل آخر
if (jid.endsWith('@lid')) jid = key.senderPn || key.remoteJidAlt || key.participantAlt || d.senderPn || d.remoteJidAlt || jid;
if (String(jid).endsWith('@lid')) throw new Error('وصل المرسل بمعرّف @lid دون رقم الجوال: ' + JSON.stringify(key));
const phone = String(jid).split('@')[0].replace(/[^0-9]/g, '');
// الرسائل المؤقتة والمعدّلة والمقتبسة تأتي مغلّفة؛ يُستخرج النص من داخلها
let m = d.message || {};
for (let i = 0; i < 4; i++) {
  const inner = (m.ephemeralMessage || m.viewOnceMessage || m.viewOnceMessageV2 || m.documentWithCaptionMessage || {}).message
    || (m.editedMessage && (m.editedMessage.message || {}).protocolMessage && m.editedMessage.message.protocolMessage.editedMessage)
    || (m.protocolMessage && m.protocolMessage.editedMessage);
  if (!inner) break;
  m = inner;
}
// الرد يخرج من الـ instance نفسه الذي استقبل الرسالة
const instance = body.instance || 'ThirdPillar';
if (!phone) return [];
const img = m.imageMessage;
if (img) {
  return [{ json: { phone, text: (img.caption || '').trim(), instance, image: true, msgId: key.id || '', mimetype: img.mimetype || 'image/jpeg',
    base64: (d.message && d.message.base64) || m.base64 || '' } }];
}
const text = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || d.text || '';
if (!text.trim()) return [];
return [{ json: { phone, text: text.trim(), instance, image: false } }];

// خطأ من قاعدة البيانات (مثل مفتاح n8n غير مطابق) يظهر أحمر في سجل التنفيذ
const res = $input.first().json;
if (res.error) throw new Error(res.error);
// الرد الفارغ: لا يُرسل شيء. سبب ذلك في res.note (رقم غير مسجَّل، أو رسالة خارج محادثة الغياب)
const reply = (res.reply || '').trim();
if (!reply) return [{ json: { skipped: res.note || 'لا رد من بوت الغياب' } }];
const src = $('استخراج الرقم والنص').first().json;
return [{ json: { number: src.phone, text: reply, instance: src.instance } }];

// رد محادثة الدوام
const res = $input.first().json;
if (res.error) throw new Error(res.error);
const reply = (res.reply || '').trim();
if (!reply) return [];
const src = $('استخراج الرقم والنص').first().json;
return [{ json: { number: src.phone, text: reply, instance: src.instance } }];

// صورة كشف الدوام: من مرسل مسموح ينتظر البوت صورته فقط (غير ذلك تُتجاهل الصورة بصمت)
const src = $input.first().json;
const PUB = 'sb_publishable_mQliqX3dKgwlKsm-u1X_gQ_8TINNIrr', K = $('المفاتيح').first().json.keys, BOT = K.BOT, EVO_KEY = K.EVO;
const sbHeaders = { apikey: PUB, Authorization: 'Bearer ' + PUB, 'Content-Type': 'application/json' };
const ok = await this.helpers.httpRequest({ method: 'POST', url: 'https://wvklhyjtzqomiyhzsfuf.supabase.co/rest/v1/rpc/staff_bot_image', headers: sbHeaders, body: { p_key: BOT, p_phone: src.phone }, json: true });
if (ok.error) throw new Error(ok.error);
// غير مسموح: لا رد (السبب يظهر في مخرجات هذه العقدة). مسموح لكن لم يبدأ بـ«دوام»: يُذكَّر
if (!ok.ok) return [{ json: ok.allowed ? { number: src.phone, text: ok.note, instance: src.instance } : { skipped: ok.note || 'تُتجاهل الصورة' } }];
const say = (text) => this.helpers.httpRequest({ method: 'POST', url: 'https://evolution.ahmedhammad.page/message/sendText/' + encodeURIComponent(src.instance),
  headers: { apikey: EVO_KEY, 'Content-Type': 'application/json' }, body: { number: src.phone, text }, json: true });
await say('وصلت الصورة، جارٍ قراءة الكشف… (قد تستغرق دقيقة)');
// الصورة نفسها: من الرسالة إن أرسلها Evolution معها، وإلا تُطلب منه
let b64 = src.base64, mime = String(src.mimetype || 'image/jpeg').split(';')[0];
if (!b64) {
  const media = await this.helpers.httpRequest({ method: 'POST', url: 'https://evolution.ahmedhammad.page/chat/getBase64FromMediaMessage/' + encodeURIComponent(src.instance),
    headers: { apikey: EVO_KEY, 'Content-Type': 'application/json' }, body: { message: { key: { id: src.msgId } }, convertToMp4: false }, json: true });
  b64 = media.base64 || '';
  if (media.mimetype) mime = String(media.mimetype).split(';')[0];
}
if (!b64) { await say('تعذر استلام الصورة. أرسلها مرة أخرى.'); throw new Error('لم تُجلب صورة الرسالة من Evolution'); }
if (!['image/jpeg', 'image/png', 'image/webp'].includes(mime)) mime = 'image/jpeg';
let res;
try {
  res = await this.helpers.httpRequest({ method: 'POST', url: 'https://wvklhyjtzqomiyhzsfuf.supabase.co/functions/v1/read-staff-sheet', headers: sbHeaders, json: true, timeout: 180000,
    body: { bot_key: BOT, phone: src.phone, file: { media_type: mime, data: b64 } } });
} catch (e) {
  await say('تعذرت قراءة الكشف الآن. أرسل الصورة مرة أخرى بعد قليل، أو ارفعها من شاشة «دوام الموظفين» في الموقع.');
  throw e;
}
if (res.ignored) return [{ json: { skipped: 'تُتجاهل الصورة (الرقم ليس بانتظار كشف)' } }];
if (res.error) { await say('تعذرت قراءة الكشف: ' + res.error); throw new Error(res.error); }
return [{ json: { number: src.phone, text: res.reply, instance: src.instance } }];

// ضع المفتاحين هنا فقط، بين علامتي التنصيص:
// BOT: من الموقع ← «الإعدادات والمستخدمون» ← «مفتاح n8n (بوت الواتساب)» ← «نسخ المفتاح»
// EVO: مفتاح Evolution API (نفسه الذي في بوت الغياب القديم)
// OPENROUTER: مفتاح openrouter.ai لتنسيق الاختبارات (اختياري؛ بدونه يعمل البوت ويُعتذر عن التنسيق)
const BOT = 'PUT_BOT_KEY_HERE';
const EVO = 'PUT_EVOLUTION_API_KEY';
const OPENROUTER = 'PUT_OPENROUTER_KEY';
if (BOT.indexOf('PUT_') === 0 || EVO.indexOf('PUT_') === 0) throw new Error('ضع المفتاحين في عقدة «المفاتيح» أولًا');
return $input.all().map((i) => ({ json: Object.assign({}, i.json, { keys: { BOT, EVO, OPENROUTER } }) }));

// تنسيق الاختبارات: «تنسيق» ثم الملف (Word أو PDF أو صورة) خلال 30 دقيقة، أو الملف مع تعليق «تنسيق».
// ما عدا ذلك يمر كما هو إلى بوت الغياب والدوام دون أي تغيير.
// اختياري: أرقام المسموح لهم بالتنسيق بصيغة دولية مفصولة بفواصل، مثل '201012345678,201098765432'. فارغ = الجميع.
const ALLOWED = '';

const item = $input.first().json;
const pass = () => [{ json: item }];
const body = item.body || item;
const d = body.data || {};
const key = d.key || {};
if (key.fromMe) return pass();
let jid = key.remoteJid || '';
if (jid.endsWith('@g.us') || jid === 'status@broadcast') return pass();
if (jid.endsWith('@lid')) jid = key.senderPn || key.remoteJidAlt || key.participantAlt || d.senderPn || d.remoteJidAlt || jid;
const phone = String(jid).split('@')[0].replace(/[^0-9]/g, '');
if (!phone || String(jid).endsWith('@lid')) return pass();
const allow = ALLOWED.split(',').map((s) => s.trim()).filter(Boolean);
if (allow.length && !allow.includes(phone)) return pass();

let m = d.message || {};
for (let i = 0; i < 4; i++) {
  const inner = (m.ephemeralMessage || m.viewOnceMessage || m.viewOnceMessageV2 || m.documentWithCaptionMessage || {}).message;
  if (!inner) break;
  m = inner;
}
const doc = m.documentMessage, img = m.imageMessage, file = doc || img;
const text = String(m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || (file && file.caption) || '').trim();

const sd = $getWorkflowStaticData('global');
sd.fmt = sd.fmt || {};
const now = Date.now();
for (const k of Object.keys(sd.fmt)) if (now - sd.fmt[k].ts > 30 * 60000) delete sd.fmt[k];

const hintOf = (t) => /ورقة/.test(t) ? 'ورقة عمل' : /(اختبار|امتحان)/.test(t) ? 'اختبار' : '';
const isCmd = /^تنسيق/.test(text);
const instance = body.instance || 'ThirdPillar';
const base = { phone, instance, keys: item.keys, msgId: key.id || '', msgKey: key };

if (isCmd && !file) {
  sd.fmt[phone] = { ts: now, hint: hintOf(text) };
  return [{ json: Object.assign(base, { fmt: 'start' }) }];
}
if (file && (isCmd || sd.fmt[phone])) {
  const hint = isCmd ? hintOf(text) : sd.fmt[phone].hint || '';
  delete sd.fmt[phone];
  return [{ json: Object.assign(base, { fmt: 'process', hint,
    fileName: (doc && doc.fileName) || '', mimetype: String(file.mimetype || '').split(';')[0],
    base64: (d.message && d.message.base64) || m.base64 || '' }) }];
}
return pass();

// تنسيق ملف المعلم بقالب الأكاديمية: قراءة الملف ← نموذج مجاني من OpenRouter ← ملف Word بالقالب ← إرساله واتساب.
// اختياري: نماذج بعينها مفصولة بفواصل (مثل 'اسم/نموذج:free'). فارغ = أفضل النماذج المجانية المتاحة الآن تلقائياً.
const MODELS = '';
// السطر الذي يظهر أسفل عنوان الاختبار (غيّره مع كل فصل)
const TERM = 'الفصل الدراسي الأول 2026/2027';

const H = this.helpers;
const src = $input.first().json;
const K = src.keys || {};
const EVO = 'https://evolution.ahmedhammad.page';
const say = (text) => H.httpRequest({ method: 'POST', url: EVO + '/message/sendText/' + encodeURIComponent(src.instance),
  headers: { apikey: K.EVO, 'Content-Type': 'application/json' }, body: { number: src.phone, text }, json: true });

if (src.fmt === 'start') {
  await say('أهلاً بك 👋\nأرسل الآن ملف الاختبار أو ورقة العمل (Word أو PDF أو صورة) وسأنسقه بقالب أكاديمية الركيزة الثالثة.\nيمكنك كتابة: تنسيق اختبار  أو  تنسيق ورقة عمل  لتحديد النوع.');
  return [{ json: { done: 'طُلب الملف من المعلم' } }];
}
const OR_KEY = String(K.OPENROUTER || '').trim();
if (!OR_KEY || OR_KEY.indexOf('PUT_') === 0) {
  await say('خدمة التنسيق غير مفعّلة بعد. تواصل مع الإدارة.');
  throw new Error('ضع مفتاح OpenRouter في عقدة «المفاتيح»');
}
await say('⏳ تم استلام الملف، جارٍ التنسيق... (قد يستغرق دقيقة أو اثنتين)');
const started = Date.now();

// ---------- 1) الملف ----------
let b64 = src.base64, mime = src.mimetype || '';
if (!b64) {
  const media = await H.httpRequest({ method: 'POST', url: EVO + '/chat/getBase64FromMediaMessage/' + encodeURIComponent(src.instance),
    headers: { apikey: K.EVO, 'Content-Type': 'application/json' }, body: { message: { key: { id: src.msgId } }, convertToMp4: false }, json: true, timeout: 60000 });
  b64 = media.base64 || '';
  if (media.mimetype) mime = String(media.mimetype).split(';')[0];
}
if (!b64) { await say('تعذر استلام الملف. أرسله مرة أخرى.'); throw new Error('لم يُجلب الملف من Evolution'); }
const ext = (String(src.fileName).split('.').pop() || '').toLowerCase();
const raw = Buffer.from(String(b64).replace(/^data:[^,]+,/, ''), 'base64');
let input;   // { kind: 'text' | 'pdf' | 'image', ... }
if (/^image\//.test(mime)) {
  input = { kind: 'image', url: 'data:' + (/(jpeg|png|webp|gif)/.test(mime) ? mime : 'image/jpeg') + ';base64,' + raw.toString('base64') };
} else if (mime === 'application/pdf' || ext === 'pdf') {
  input = { kind: 'pdf', url: 'data:application/pdf;base64,' + raw.toString('base64') };
} else if (ext === 'docx' || /officedocument\.wordprocessingml/.test(mime) || (raw[0] === 0x50 && raw[1] === 0x4b)) {
  let lines = [];
  try { lines = docxLines(raw); } catch (e) { lines = []; }
  if (lines.map((l) => l.text || '').join('').replace(/\s/g, '').length < 20) { await say('❌ لم أستطع قراءة نص ملف Word. أرسله بصيغة PDF أو صورة واضحة.'); return [{ json: { skipped: 'docx بلا نص مقروء' } }]; }
  input = { kind: 'word', lines: lines.slice(0, 600) };
} else {
  await say('❌ صيغة الملف غير مدعومة. أرسل ملف Word (docx) أو PDF أو صورة.\nإن كان الملف بصيغة doc القديمة: افتحه في Word واحفظه باسم docx.');
  return [{ json: { skipped: 'صيغة غير مدعومة: ' + (mime || ext) } }];
}

// ---------- 2) النموذج ----------
let candidates = MODELS.split(',').map((s) => s.trim()).filter(Boolean);
if (!candidates.length) {
  const r = await H.httpRequest({ method: 'GET', url: 'https://openrouter.ai/api/v1/models', json: true, timeout: 20000 });
  const free = (r.data || []).filter((x) => /:free$/.test(x.id));
  const ins = (x) => ((x.architecture && x.architecture.input_modalities) || []);
  const byCtx = (a, b) => (b.context_length || 0) - (a.context_length || 0);
  const vision = free.filter((x) => ins(x).includes('image')).sort(byCtx).map((x) => x.id);
  const textual = free.filter((x) => !ins(x).includes('image')).sort(byCtx).map((x) => x.id);
  candidates = input.kind === 'image' ? vision.slice(0, 4) : vision.slice(0, 3).concat(textual.slice(0, 2));
}
if (!candidates.length) { await say('❌ لا يتوفر الآن نموذج ذكاء اصطناعي مجاني مناسب. أعد المحاولة لاحقاً.'); throw new Error('لا نماذج مجانية مناسبة على OpenRouter'); }

function pickJson(s) {
  s = String(s || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (_) {}
  try { return JSON.parse(s.slice(a, b + 1).replace(/,\s*([}\]])/g, '$1')); } catch (_) { return null; }
}
// يجرّب النماذج بالترتيب حتى يقبل check الرد: { value } | { reject } ، ويُرجع أفضل رد مرفوض احتياطاً
const errors = [];
let limited = 0;
async function askModels(system, content, plugins, check) {
  let fallback = null;
  for (const model of candidates) {
    const left = 230000 - (Date.now() - started);
    if (left < 25000) break;
    let res;
    try {
      res = await H.httpRequest({
        method: 'POST', url: 'https://openrouter.ai/api/v1/chat/completions', json: true,
        headers: { Authorization: 'Bearer ' + OR_KEY, 'Content-Type': 'application/json', 'X-Title': 'TPA Formatter' },
        body: Object.assign({ model, temperature: 0, max_tokens: 12000, messages: [{ role: 'system', content: system }, { role: 'user', content }] }, plugins ? { plugins } : {}),
        timeout: Math.min(150000, left - 15000), returnFullResponse: true, ignoreHttpStatusErrors: true,
      });
    } catch (e) { errors.push(model + ': ' + String(e.message || e).slice(0, 120)); continue; }
    const body = res.body || {};
    if (res.statusCode === 429 || (body.error && body.error.code === 429)) { limited++; errors.push(model + ': 429'); continue; }
    if (res.statusCode >= 400 || body.error) { errors.push(model + ': ' + res.statusCode + ' ' + JSON.stringify(body.error || body).slice(0, 150)); continue; }
    const r = check(pickJson(((body.choices || [])[0] || {}).message ? body.choices[0].message.content : ''));
    if (r.value) return { value: r.value, model };
    errors.push(model + ': ' + r.reject);
    if (r.fallback && (!fallback || r.score < fallback.score)) fallback = { value: r.fallback, model, score: r.score, note: r.note };
  }
  return fallback ? { value: fallback.value, model: fallback.model, note: fallback.note } : null;
}

let exam = null, usedModel = '', doubt = '';
if (input.kind === 'word') {
  // ===== ملف Word: النص يُنقل من الملف حرفياً، والنموذج يرتّب الأسطر بأرقامها فقط ولا يكتب نصاً =====
  const L = input.lines;
  const show = (l) => 'L' + l.id + ': ' + (l.table ? '[جدول] ' + l.table.map((r) => r.join(' | ')).join(' ؛ ') : l.image ? '[صورة]' : l.empty ? '[سطر فارغ]' : l.text);
  const SYSTEM_WORD = 'أنت تنظّم ملف اختبار أو ورقة عمل كتبه معلم في Word، لوضعه في قالب أكاديمية الركيزة الثالثة.\n' +
    'ستصلك أسطر الملف مرقمة (L1، L2، ...). لا تكتب أي نص من عندك ولا تنسخ النصوص: أشر إلى الأسطر بأرقامها فقط، فالنص يؤخذ من الملف كما هو.\n' +
    'أعد كائن JSON واحداً فقط بلا شرح:\n' +
    '{"kind":"اختبار" أو "ورقة عمل","subject":"المادة","grade":"الصف ...","total":"الدرجة الكلية كما في الملف أو \'\'","drop":[أرقام],"heads":[أرقام],"types":{"رقم":"h|center|passage"}}\n' +
    '- drop: أسطر ترويسة المدرسة الأخرى فقط: اسم المدرسة أو الجهة، الشعار، خانات اسم الطالب والصف والشعبة والدرجة والتاريخ والزمن، وسطر عنوان الاختبار/المادة/الصف في الأعلى (القالب يكتبها). لا تحذف البسملة ولا التعليمات العامة ولا أي سؤال.\n' +
    '- heads: أرقام أسطر عناوين الأسئلة الرئيسية بالترتيب، مثل «السؤال الأول: ...» أو «س1: ...» أو «أولاً: ...». الفروع (١- ، أ- ...) ليست عناوين.\n' +
    '- types (اختياري): h لعنوان فرعي داخل السؤال، center لسطر في المنتصف مثل بنك الكلمات، passage لفقرة قراءة طويلة. باقي الأسطر عادية فلا تذكرها.\n' +
    '- subject وgrade مثل "اللغة العربية" و"الصف الثالث". إن لم يُذكر الصف اكتب "الصف .........".';
  const note = src.hint ? 'نوع الملف حسب رسالة المعلم: ' + src.hint : 'استنتج نوع الملف من محتواه.';
  const ids = new Set(L.map((l) => l.id));
  const okPlan = (p) => {
    if (!p || !Array.isArray(p.heads)) return { reject: 'رد غير صالح' };
    const heads = p.heads.map(Number).filter((n) => ids.has(n) && L[n - 1].text);
    if (!heads.length) return { reject: 'لم يحدد عناوين الأسئلة' };
    return { value: Object.assign({}, p, { heads, drop: (p.drop || []).map(Number).filter((n) => ids.has(n) && !heads.includes(n)) }) };
  };
  const got = await askModels(SYSTEM_WORD, note + '\n\n' + L.map(show).join('\n'), null, okPlan);
  let plan;
  if (got) { plan = got.value; usedModel = got.model; }
  else {
    // دون نموذج: عناوين الأسئلة من صيغتها، وما قبل أول سؤال ترويسة (إلا البسملة)
    const isHead = (t) => /^[\s\u200E\u200F]*(السؤال|س\s*[0-9٠-٩]|[أا]ولاً|[أا]ولا\s*[:：]|ثانياً|ثالثاً|رابعاً|خامساً|سادساً)/.test(t || '');
    const heads = L.filter((l) => isHead(l.text)).map((l) => l.id);
    if (!heads.length) {
      await say(limited && limited === errors.length
        ? '⏳ تم بلوغ حد الاستخدام المجاني لخدمة الذكاء الاصطناعي حالياً. أعد المحاولة بعد قليل بإرسال: تنسيق'
        : '❌ لم أتعرف على أسئلة الملف. تأكد أن كل سؤال يبدأ بكلمة «السؤال» وأعد المحاولة بإرسال: تنسيق');
      return [{ json: { failed: true, errors } }];
    }
    plan = { kind: src.hint || 'اختبار', subject: '.........', grade: 'الصف .........', total: '', heads,
      drop: L.filter((l) => l.id < heads[0] && !/بسم\s*الله/.test(l.text || '')).map((l) => l.id), types: {} };
    usedModel = 'بدون نموذج';
    doubt = '\n⚠️ لم تتوفر خدمة الذكاء الاصطناعي، فرُتّب الملف تلقائياً: تأكد من المادة والصف وحذف ترويسة المدرسة الأخرى.';
  }
